    ["Inworld key"] = "Inworld-kulcs",
    ["Paste Inworld key"] = "Inworld-kulcs beillesztése",
    ["Remove my Inworld key"] = "Inworld-kulcsom eltávolítása",
    ["The Inworld cloud voice speaks only English here. Turn off Multilingual conversations to choose it."] = "Az Inworld felhőhang itt csak angolul beszél. A kiválasztásához kapcsold ki a Többnyelvű beszélgetések beállítást.",
    ["{voice} · needs Inworld key"] = "{voice} · Inworld-kulcs szükséges",
    ["Characters to invite"] = "Meghívható karakterek",
    ["Whose memories"] = "Kinek az emlékei",
    ["Invalid Mature content settings."] = "Érvénytelen felnőtt tartalom beállítások.",
    ["Your message was not sent. Open the text box again and retype it."] = "Az üzeneted nem lett elküldve. Nyisd meg újra a szövegmezőt, és írd be még egyszer.",
    ["Not usable: {models}. See the Local AI notes, \"Add your own model\"."] = "Nem használható: {models}. Lásd a Helyi MI megjegyzéseit: „Saját modell hozzáadása“.",
    ["an embedding model, not a chat model"] = "beágyazó (embedding) modell, nem csevegőmodell",
    ["could not be read"] = "nem sikerült beolvasni",
    ["file not found"] = "a fájl nem található",
    ["not a valid GGUF file"] = "nem érvényes GGUF-fájl",
    ["{name} (custom)"] = "{name} (egyéni)",
    ["{name}: {reason}"] = "{name}: {reason}",
    ["Preparing {name}: waiting for the conversation service to connect…"] = "{name} előkészítése: várakozás a beszélgetési szolgáltatás csatlakozására…",
    ["Preparing {name}: waiting for the voice model to load…"] = "{name} előkészítése: várakozás a hangmodell betöltésére…",
    ["Preparing {name}: waiting for the conversation connection to open…"] = "{name} előkészítése: várakozás a beszélgetési kapcsolat megnyitására…",
    ["Preparing {name}: waiting for the game to place the character…"] = "{name} előkészítése: várakozás, amíg a játék elhelyezi a karaktert…",
    ["Preparing {name}: waiting for the memory service…"] = "{name} előkészítése: várakozás az emlékszolgáltatásra…",
    ["Preparing {count} more companions…"] = "További {count} társ előkészítése…",
    ["The conversation service did not answer. Wait a moment, then invite again."] = "A beszélgetési szolgáltatás nem válaszolt. Várj egy kicsit, majd hívd meg újra.",
    ["The voice model did not load. Check the voice in Settings or choose another one, then invite again."] = "A hangmodell nem töltődött be. Nézd meg a hangot a Beállításokban, vagy válassz másikat, majd hívd meg újra.",
    ["The memory service did not respond. Check your connection, then invite again."] = "Az emlékszolgáltatás nem válaszolt. Ellenőrizd a kapcsolatot, majd hívd meg újra.",
    ["The conversation connection did not open. Check your connection, then invite again."] = "A beszélgetési kapcsolat nem nyílt meg. Ellenőrizd a kapcsolatot, majd hívd meg újra.",
    ["Calls are not available during combat."] = "Hívások harc közben nem elérhetők.",
    ["Calls are not available right now."] = "Most nem érhetők el a hívások.",
    ["Holocall ended: combat started."] = "A holohívás véget ért: harc kezdődött.",
    ["Holocall with {name} ended."] = "Véget ért a holohívás ({name}).",
    ["Holocall with {name}. Tap the phone button to hang up."] = "Holohívás: {name}. A leteszeshez koppints a telefon gombra.",
    ["Live holocall picture (experimental)"] = "Élő kép a holohíváshoz (kísérleti)",
    ["Live picture unavailable. The call continues with the portrait."] = "Az élő kép nem elérhető. A hívás a portréval folytatódik.",
    ["This contact cannot take a holocall."] = "Ez a névjegy nem fogadhat holohívást.",
    ["You are already on a call."] = "Már hívásban vagy.",
    ["A nearby companion makes one short comment as combat starts and another afterward.\n\nTen-minute cooldown after a fight. Conversations and story scenes come first. Loading a save resets the cooldown."] = "A közeli társ rövid megjegyzést tesz a harc kezdetén, és egy másikat utána.\n\nHarc után tíz perces szünet. A beszélgetések és a történetjelenetek élveznek elsőbbséget. Mentés betöltése nullázza a szünetet.",
    ["Ask a companion to drive to your selected map waypoint.\n\nGet into the passenger seat when they are ready."] = "Kérd meg a társat, hogy vezessen a kijelölt térképi ponthoz.\n\nAmikor készen állnak, ülj be az utasülésre.",
    ["Auto: follows the completed encounter in this save.\n\nCasual: speaks with that familiarity.\n\nOrdinary: keeps her usual manner.\n\nIt does not imply an ongoing relationship."] = "Automatikus: a mentésben lezárult találkozáshoz igazodik.\n\nLaza: ezzel a bizalmassággal beszél.\n\nHétköznapi: megtartja szokásos modorát.\n\nNem jelent tartós kapcsolatot.",
    ["Auto: follows the relationship in this save.\n\nRomantic: speaks to V as a partner.\n\nOrdinary: keeps their usual manner.\n\nOnly changes how they talk, never your game choices."] = "Automatikus: a mentésben lévő kapcsolathoz igazodik.\n\nRomantikus: V-hez partnerként szól.\n\nHétköznapi: megtartja szokásos modorát.\n\nCsak a beszédmódot változtatja, sosem a játékbeli döntéseidet.",
    ["Bluetooth audio arrives a little late, so lips and subtitles can run ahead of the voice. This holds them back to match, for every voice.\n\nAuto: 150 ms while Windows plays through Bluetooth, none otherwise. Pick a value if your headset is faster or slower.\n\nThe game’s own dialogue has the same delay and does not correct it."] = "A Bluetooth-hang kicsit később érkezik, így az ajak és a feliratok megelőzhetik a hangot. Ez minden hanghoz visszatartja őket, hogy egyezzenek.\n\nAutomatikus: 150 ms, amíg a Windows Bluetoothon játszik, egyébként nincs. Adj meg értéket, ha a fejhallgatód gyorsabb vagy lassabb.\n\nA játék saját párbeszédei ugyanezzel a késéssel bírnak, és nem korrigálja.",
    ["Changes this mod’s menus and notices only.\n\nCharacter voices and the language you talk in are separate."] = "Csak ennek a modnak a menüit és értesítéseit változtatja.\n\nA karakterek hangjai és az általad használt nyelv külön vannak.",
    ["Characters sometimes ask about something you said, pick up something from earlier or share a thought that invites an answer.\n\nNow and then, never on every reply, and never while you are leaving, giving an order or fighting."] = "A karakterek néha kérdeznek arra, amit mondtál, felvesznek valamit korábbról, vagy olyan gondolatot osztanak meg, amire választ lehet adni.\n\nÉlnek vele időnként, sosem minden válasznál, és sosem akkor, amikor távozol, parancsot adsz vagy harcolsz.",
    ["Chat history stays available across game launches.\n\nForgetting a character also clears their saved Chat messages and drafts. Forgetting all memories clears all saved chats."] = "A csevegési előzmények a játék indításai között is elérhetők maradnak.\n\nEgy karakter elfelejtése törli a mentett Csevegés-üzeneteit és piszkozatait is. A minden emlék elfelejtése minden mentett csevegést töröl.",
    ["Cinematic: the game’s regular dialogue subtitles.\n\nAbove the speaker: over the companion who is talking.\n\nThe Subtitles switch turns both off."] = "Filmes: a játék szokásos párbeszédfeliratai.\n\nA beszélő felett: a beszélő társ fölött.\n\nA Feliratok kapcsoló mindkettőt kikapcsolja.",
    ["Companions comment after you finish collecting loot from the world. Storage transfers stay silent.\n\nOrdinary comments are ten minutes apart; newly acquired Legendary gear has its own two-minute cooldown.\n\nPickups made during a fight are folded into one comment at its end."] = "A társak a világ zsákmányának összegyűjtése után kommentálnak. A tárolóba történő átvitelek néma maradnak.\n\nA szokásos megjegyzések tíz perc távolságra vannak; az újonnan szerzett Legendary felszerelés saját két perces szünettel rendelkezik.\n\nHarc közben szerzett tárgyak a harc végén egy megjegyzésbe vannak összevonva.",
    ["Companions gesture while they speak longer replies and nod while you talk, with the game’s own animations in their usual stance.\n\nThey stop at once when anyone moves or a fight starts."] = "A társak hosszabb válaszoknál gesztikulálnak, miközben beszélnek, és bólogatnak, amikor te beszélsz, a játék saját animációival, szokásos tartásukban.\n\nAzonnal abbahagyják, amint bárki mozog vagy harc kezdődik.",
    ["Companions now and then pause, hesitate, laugh or sigh, as their personality would. Each character decides when; it stays rare.\n\nOmniVoice and Inworld can voice laughs and sighs; the other voices only add pauses.\n\nNot available with Convai’s cloud voice: choosing it turns this off, and turning this on switches the voice to Pocket."] = "A társak időnként megtorpannak, habozhatnak, nevethetnek vagy sóhajthatnak, személyiségüknek megfelelően. Minden karakter eldönti, mikor; ez ritka marad.\n\nAz OmniVoice és az Inworld tud nevetni és sóhajtani; a többi hang csak szüneteket ad.\n\nA Convai felhőhangjával nem elérhető: annak kiválasztása kikapcsolja ezt, a bekapcsolása pedig a hangot Pocketre váltja.",
    ["Copy your free key from Mistral first. It is read from the clipboard once, checked with Mistral and saved on this computer.\n\nYou can also save it in player-mistral-key.txt in the conversation service folder."] = "Először másold ki a szabad Mistral-kulcsodat. A vágólapról egyszer olvassuk be, a Mistral ellenőrzi, és ezen a számítógépen mentjük.\n\nA beszélgetési szolgáltatás mappájában a player-mistral-key.txt fájlba is mentheted.",
    ["Copy your key from Inworld first. It is read from the clipboard once, checked with Inworld and saved on this computer.\n\nYou can also save it in player-inworld-key.txt in the conversation service folder. It is used only for the Inworld voice."] = "Először másold ki az Inworld-kulcsodat. A vágólapról egyszer olvassuk be, az Inworld ellenőrzi, és ezen a számítógépen mentjük.\n\nA beszélgetési szolgáltatás mappájában a player-inworld-key.txt fájlba is mentheted. Csak az Inworld hangjához használjuk.",
    ["Custom models are ones you added; they join the default choice by size."] = "Az egyéni modelleket te adtad hozzá; méret szerint az alapértelmezetthez csatlakoznak.",
    ["Each character marks its own feelings as it speaks, so the face changes at that word instead of being guessed from the text. Subtle, set by personality, only where a feeling really shifts.\n\nInworld always speaks with emotion, whatever this says.\n\nNot available with Convai’s cloud voice: choosing it turns this off, and turning this on switches the voice to Pocket."] = "Minden karakter a beszéd közben jelzi az érzéseit, így az arc a szónál változik, nem a szövegből találgatva. Finoman, a személyiség szerint, csak ahol az érzés valóban változik.\n\nAz Inworld mindig érzelemmel beszél, bármit is mond ez a beállítás.\n\nA Convai felhőhangjával nem elérhető: annak kiválasztása kikapcsolja ezt, a bekapcsolása pedig a hangot Pocketre váltja.",
    ["Eyes only: the head stays still and just the eyes move.\n\nSubtle to Strong: the head turns toward you more and more."] = "Csak szem: a fej mozdulatlan marad, csak a szemek mozognak.\n\nVisszafogottól Erősig: a fej egyre jobban fordul felénk.",
    ["For testing and bug reports; leave it off for normal play.\n\nShows routine popups (joining steps, dismissals, driving instructions, results of companion actions), writes a movement trace in the mod’s runtime folder, logs gesture decisions and adds itself to support reports.\n\nPreparation progress, joined notices, failures and replies to Stop trip stay visible when it is off."] = "Teszteléshez és hibajelentéshez; normál játéknál hagyd kikapcsolva.\n\nMegjeleníti a rutin felugró ablakokat (csatlakozási lépések, elutasítások, vezetési utasítások, társi műveletek eredményei), mozgásnaplót ír a mod futásidejű mappájába, naplózza a gesztusdöntéseket, és bekerül a támogatási jelentésekbe.\n\nA felkészítés előrehaladása, a csatlakozási értesítések, a hibák és az Út leállítása válaszok kikapcsolt állapotban is láthatók maradnak.",
    ["Forget all memories applies to these characters.\n\nBrowsing the catalogue or inviting a companion does not add anyone to this count."] = "A minden emlék elfelejtése ezekre a karakterekre vonatkozik.\n\nA katalógus böngészése vagy társ meghívása nem ad hozzá senkit ehhez a számhoz.",
    ["Gang members, NCPD officers, guards, ripperdocs, shopkeepers, bartenders and passers-by answer as their kind of person.\n\nThey do not know your story and forget you after a save load, except shopkeepers you come back to.\n\nNamed characters are not affected."] = "A bandatagok, NCPD-tisztek, őrök, ripperdocok, boltosok, csaposok és járókelők a saját típusuk szerint válaszolnak.\n\nNem ismerik a történetedet, és mentés betöltése után elfelejtenek, kivéve azokat a boltosokat, akikhez visszatérsz.\n\nAz elnevezett karakterek nem érintettek.",
    ["Gets a conversation ready when you look at, approach or have just talked to a character, so they answer without a wait. Paused in combat and scenes.\n\nLimits: two characters ready at once, a new one every 3 s, released after 40 s unused. A crowd never adds up."] = "Előkészít egy beszélgetést, amikor egy karakterre nézel, hozzá közelítesz vagy most beszéltél vele, így várakozás nélkül válaszol. Harcban és jelenetekben szünetel.\n\nKorlátok: egyszerre két karakter készen áll, új 3 másodpercenként, 40 másodperc használaton kívül után felszabadul. A tömeg sosem adódik össze.",
    ["If a character stops answering, voices stop or an error appears: choose Generate report and send the file it names to the developer, with a short note about what you were doing.\n\nThe logs listed below show what went wrong."] = "Ha egy karakter nem válaszol, a hangok leállnak vagy hiba jelenik meg: válaszd a Jelentés létrehozása opciót, és küldd el a fejlesztőnek a megnevezett fájlt, rövid megjegyzéssel arról, mit csináltál.\n\nAz alább felsorolt naplók mutatják, mi ment rosszul.",
    ["Invited characters are prepared immediately. Their memories start when you actually talk to them.\n\nOne player identity is shared across all saves and stays the same after forgetting.\n\nCurrent game context describes the world you have loaded."] = "A meghívott karakterek azonnal előkészítésre kerülnek. Emlékeik akkor indulnak, amikor valóban beszélsz velük.\n\nEgy játékosazonosító minden mentés között közös, és az elfelejtés után is ugyanaz marad.\n\nA jelenlegi játékkontextus a betöltött világot írja le.",
    ["Inworld · Cloud voice"] = "Inworld · Felhőhang",
    ["Inworld · needs key"] = "Inworld · kulcs kell",
    ["Judy, Panam, River, Kerry and Meredith can speak as a partner or in their ordinary manner.\n\nAuto follows the relationship in your save."] = "Judy, Panam, River, Kerry és Meredith partnerként vagy hétköznapi modorában is beszélhet.\n\nAz Automatikus a mentésben lévő kapcsolathoz igazodik.",
    ["Needs the Local AI pack."] = "A Helyi MI-csomag szükséges.",
    ["Never allowed: sex with minors or without consent, sex about real people, hate, real-world weapon or drug instructions. A safety check enforces the minors rule."] = "Tilos: szex kiskorúval vagy beleegyezés nélkül, valódi személyekkel, gyűlölet, valós fegyver- vagy drogútmutató. Biztonsági ellenőrzés védi a kiskorúakat.",
    ["Not using Local AI right now: no effect yet."] = "Helyi MI most nem fut: még nincs hatása.",
    ["Off: replies are text only and no voice is generated.\n\nWith Subtitles off as well, automatic reactions stay silent."] = "Ki: a válaszok csak szövegesek, és nincs hanggenerálás.\n\nHa a Feliratok is ki vannak kapcsolva, az automatikus reakciók csendben maradnak.",
    ["Pocket: the lightest, runs on your CPU, starts speaking in about 0.2 s.\n\nOmniVoice: richer, especially on harder voices. Needs a capable GPU and the OmniVoice pack; the higher tiers start in 1 to 2.5 s.\n\nVoxtral and Inworld: each companion’s own voice from the cloud, with your own key, English only. Inworld also speaks with emotion. They load no local voice model.\n\nConvai: its own cloud voice. A voice that cannot run is replaced by a simpler one, with one notice."] = "Pocket: a legkönnyebb, a processzoron fut, kb. 0,2 mp alatt megszólal.\n\nOmniVoice: gazdagabb, főleg nehezebb hangokon. Erős GPU-t és az OmniVoice-csomagot igényel; a magasabb szintek 1–2,5 mp alatt indulnak.\n\nVoxtral és Inworld: minden társ saját hangja a felhőből, saját kulccsal, csak angolul. Az Inworld érzelemmel is beszél. Nem töltenek be helyi hangmodellt.\n\nConvai: saját felhőhangja. A nem futtatható hangot egy egyszerűbb váltja fel, egyetlen értesítéssel.",
    ["Right after the game’s own dialogue with a character, they know its last few lines, including your chosen replies and your phone calls with them.\n\nOnly the last few minutes count, and none of it is saved to memory."] = "Közvetlenül a játék saját, karakterrel folytatott párbeszéde után ismerik utolsó néhány sorát, beleértve a te választott válaszaidat és a vele folytatott telefonhívásaidat.\n\nCsak az utolsó néhány perc számít, és ebből semmi sem kerül a memóriába.",
    ["Runs conversations on this computer with the optional Local AI pack. It needs free graphics memory while it works.\n\nChoose Local in Conversation provider, then Apply."] = "Beszélgetéseket futtat ezen a számítógépen az opcionális Helyi MI-csomaggal. Működés közben szabad grafikus memóriát igényel.\n\nVálaszd a Beszélgetési szolgáltató beállításnál a Helyi lehetőséget, majd az Alkalmaz gombot.",
    ["See what each character remembers and make one or all of them forget.\n\nMemories are kept across saves."] = "Megnézheted, mit jegyez meg az egyes karakter, és egyet vagy mindegyiket elfelejtetheted.\n\nAz emlékek a mentések között megmaradnak.",
    ["Shows companion replies as text.\n\nWith Voice playback off as well, automatic reactions stay silent."] = "A társ válaszait szövegként mutatja.\n\nHa a Hanglejátszás is ki van kapcsolva, az automatikus reakciók csendben maradnak.",
    ["Shows the character live in a holocall instead of their portrait.\n\nExperimental: the picture can stay empty. If she cannot be shown, the call goes on with the portrait."] = "A karaktert élőben mutatja egy holohívásban a portré helyett.\n\nKísérleti: a kép üres maradhat. Ha nem lehet megmutatni, a hívás a portréval folytatódik.",
    ["Strong language, graphic violence, drugs and, between consenting adults, flirting and sex. Adults only (18+), Local AI only."] = "Erős nyelv, kegyetlen erőszak, drogok, beleegyező felnőttek közt flört és szex. Csak felnőtteknek (18+), csak Helyi MI-vel.",
    ["Talk in any language; each character answers in yours.\n\nA separate multilingual copy of each character is used, so what they remember from these talks stays apart from your English ones. Forgetting a character clears both.\n\nPocket, Voxtral and Inworld speak English only, so this switches the voice to OmniVoice · Balanced, or to Convai · Cloud voice without the OmniVoice pack. Without the pack, Natural speech and Expressive emotions turn off."] = "Beszélj bármilyen nyelven; minden karakter a tiedjén válaszol.\n\nMinden karakternek külön többnyelvű másolata van, így amit ezekből a beszélgetésekből megjegyez, elkülönül az angol beszélgetéseidtől. Egy karakter elfelejtése mindkettőt törli.\n\nA Pocket, a Voxtral és az Inworld csak angolul beszél, ezért ez a hangot OmniVoice · Kiegyensúlyozottra vagy OmniVoice-csomag nélkül Convai · Felhőhangra váltja. Csomag nélkül a Természetes beszéd és a Kifejező érzelmek kikapcsol.",
    ["Turn AI conversations on or off for each character.\n\nA character that is off can still follow you."] = "Minden karakter AI-beszélgetéseit be- vagy kikapcsolhatod.\n\nA kikapcsolt karakter így is követhet téged.",
    ["Turning it on also selects Local AI, the largest uncensored model that fits and a local voice instead of a cloud one. Turning it off restores your choices."] = "Bekapcsolva a Helyi MI-t is kiválasztja, a legnagyobb belférő cenzúrázatlan modellt, és helyi hangot a felhős helyett. Kikapcsolva visszaáll a választás.",
    ["Use it if companions seem to look above or below your eyes."] = "Használd, ha úgy tűnik, hogy a társak a szemed fölé vagy alá néznek.",
    ["Use your own Convai key for conversations: paste it below, turn this on, choose Apply.\n\nThe change waits until no conversation is running."] = "Beszélgetésekhez használd a saját Convai-kulcsodat: illeszd be lentebb, kapcsold be, és válaszd az Alkalmaz lehetőséget.\n\nA változtatás addig vár, amíg nem fut beszélgetés.",
    ["Voxtral · Mistral cloud"] = "Voxtral · Mistral felhő",
    ["Voxtral · needs Mistral key"] = "Voxtral · Mistral-kulcs kell",
    ["When you type a line, V says it out loud too, in the male or female V voice that matches yours. Push-to-talk is never replayed.\n\nV speaks first, then the companion answers. A slow V line is skipped, so the reply is never delayed.\n\nUses the voice chosen above, cloned for V."] = "Amikor beírsz egy sort, V is hangosan kimondja a te nemednek megfelelő férfi vagy női V-hangon. A push-to-talk felvétel sosem játszódik le újra.\n\nV először beszél, aztán válaszol a társ. A lassú V-sor kimarad, így a válasz sosem késik.\n\nA fent kiválasztott hangot használja, V-re klónozva.",
    ["Who answers your conversations right now.\n\nA change of provider waits until no conversation is running."] = "Ki válaszol most a beszélgetéseidre.\n\nA szolgáltató váltása addig vár, amíg nem fut beszélgetés.",
    ["{name} (custom · too large)"] = "{name} (egyéni · túl nagy)",
    ["{name} (custom, {size} GB, needs {need} GB)"] = "{name} (egyéni, {size} GB, {need} GB kell)",
    ["{name} (custom, {size} GB, too large for this card)"] = "{name} (egyéni, {size} GB, túl nagy ehhez a videokártyához)",
    ["{voice} · needs pack"] = "{voice} · csomag kell",
    ["Clear memories about you for every character you have talked to.\n\nYour player identity stays. A confirmation comes first."] = "Töröld a rólad szóló emlékeket minden karakternél, akivel beszéltél.\n\nA játékosazonosságod megmarad. Előbb megerősítést kell adnod.",
    ["Plays one of this character’s own lines from the game, to compare with their companion voice.\n\nYou hear it when you return to gameplay. Each press tries another line; some characters have none."] = "Lejátssza a karakter egyik saját, játékbeli sorát, hogy összehasonlíthasd a társhangjával.\n\nVisszatérve a játékba hallod. Minden nyomás másik sort próbál; egyes karaktereknek nincs.",
    ["Saves a report file you can send to the developer.\n\nAPI keys, tokens, IDs, microphone audio and conversation text are left out. Without the conversation service, a shorter report is made from the files the game can read."] = "Mentsd el a fejlesztőnek elküldhető jelentésfájlt.\n\nAz API-kulcsok, tokenek, azonosítók, mikrofonhang és beszélgetésszöveg kimaradnak. A beszélgetési szolgáltatás nélkül rövidebb jelentés készül a játék által olvasható fájlokból.",
    ["The Mature pack’s uncensored models give the full effect; standard models mostly refuse sex. Pack: installed."] = "Cenzúrázatlan Mature-modellek: teljes hatás; sima modellek többnyire nem vállalnak szexet. Csomag: telepítve.",
    ["The Mature pack’s uncensored models give the full effect; standard models mostly refuse sex. Pack: not installed (optional, on this mod’s GitHub page)."] = "Cenzúrázatlan Mature-modellek: teljes hatás; sima modellek többnyire nem vállalnak szexet. Csomag: nincs telepítve (opcionális, GitHub-oldal).",
    ["Until you choose one, Local AI loads the largest model that fits your free graphics memory.\n\nOne model at a time; a change applies when it next loads. A model that is missing, too large or failing is replaced by the largest that fits, with one notice."] = "Amíg nem választasz, a Helyi MI a szabad videomemóriába férő legnagyobb modellt tölti be.\n\nEgyszerre egy modell; a változás a következő betöltéskor lép életbe. A hiányzó, túl nagy vagy hibás modellt a legnagyobb befér modell váltja, egy értesítéssel.",
    ["Body gestures"] = "Testgesztusok",
    ["Convai did not accept your API key. Check it in Settings > Conversation provider."] = "A Convai nem fogadta el az API-kulcsodat. Ellenőrizd a Beállítások > Beszélgetési szolgáltató menüpontban.",
    ["Local AI could not start, so a cloud provider is used. Check Local AI in Settings > Conversation provider."] = "A helyi MI nem tudott elindulni, ezért felhőszolgáltató van használatban. Ellenőrizd a helyi MI-t a Beállítások > Beszélgetési szolgáltató menüpontban.",
    ["Local AI could not start. Check Local AI in Settings > Conversation provider."] = "A helyi MI nem tudott elindulni. Ellenőrizd a helyi MI-t a Beállítások > Beszélgetési szolgáltató menüpontban.",
    ["Mistral did not accept your key. Check it in Settings > Conversation provider."] = "A Mistral nem fogadta el a kulcsodat. Ellenőrizd a Beállítások > Beszélgetési szolgáltató menüpontban.",
    ["Mistral has no key yet, so Convai is used. Add your key in Settings > Conversation provider."] = "A Mistral-hoz még nincs kulcs, ezért a Convai van használatban. Add meg a kulcsodat a Beállítások > Beszélgetési szolgáltató menüpontban.",
    ["Requires a Mistral key (add it in Settings > Conversation provider)"] = "Mistral-kulcs szükséges (add hozzá a Beállítások > Beszélgetési szolgáltató menüpontban)",
    ["Requires an Inworld key (add it in Settings > Voices)"] = "Inworld-kulcs szükséges (add hozzá a Beállítások > Hangok menüpontban)",
    ["Speaking to companions needs Convai for now. Set Conversation provider to Convai free tier in Settings > Conversation provider, or type your message."] = "A társakkal való beszélgetéshez egyelőre Convai kell. Állítsd a Beszélgetési szolgáltató értékét Convai (ingyenes csomag) értékre a Beállítások > Beszélgetési szolgáltató menüpontban, vagy írd be az üzenetedet.",
    ["The conversation limit has been reached. Try again later, or add a free Mistral key and set Conversation provider to Mistral in Settings > Conversation provider."] = "Elérted a beszélgetési keretet. Próbáld újra később, vagy adj meg egy ingyenes Mistral-kulcsot, és a Beállítások > Beszélgetési szolgáltató menüpontban állítsd a Beszélgetési szolgáltató beállítást Mistralra.",
    ["Your Convai API key has reached its plan limit. Try again later or add a different key in Settings > Conversation provider."] = "A Convai API-kulcsod elérte a csomag keretét. Próbáld újra később, vagy adj meg másik kulcsot a Beállítások > Beszélgetési szolgáltató menüpontban.",
    ["You’ve reached today’s free conversation limit. Convai (better quality responses) is back tomorrow. To keep talking now, add a free Mistral key and set Conversation provider to Mistral in Settings > Conversation provider. A fully local option is coming."] = "Elérted a mai ingyenes beszélgetési keretet. A Convai (jobb minőségű válaszok) holnap újra elérhető. Ha most folytatnál, adj meg egy ingyenes Mistral-kulcsot, és a Beállítások > Beszélgetési szolgáltató menüpontban állítsd a Beszélgetési szolgáltató beállítást Mistralra. Egy teljesen helyi lehetőség is készül.",
    ["Convai is answering right now, so these changes have no effect yet. Choose Mistral or Local as the conversation provider in the settings."] = "A Convai most válaszol, ezért ezek a módosítások még nem hatnak. A beállításokban válaszd a Mistral vagy a Local beszélgetési szolgáltatót.",
    ["Edit a character’s bio, speaking style, speaking rules and memories in your browser.\n\nWorks with Mistral and Local, not Convai. Changes apply from the next reply."] = "Szerkeszd egy karakter életrajzát, beszédstílusát, beszédszabályait és emlékeit a böngésződben.\n\nMistral és Helyi esetén működik, Convai esetén nem. A változtatások a következő választól lépnek életbe.",
    ["Who writes your companions’ replies. A change waits until no conversation is running; choose Apply.\n\nConvai needs no setup and gives better replies. Mistral uses its free plan with your own free key (signing up needs phone verification); memory stays on this computer.\n\nMistral allows about one message a second and a monthly allowance.\n\nWith Mistral or Local, Convai’s cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works."] = "Ki írja a társaid válaszait. A változtatás addig vár, amíg nem fut beszélgetés; válaszd az Alkalmaz lehetőséget.\n\nA Convai nem igényel beállítást, és jobb válaszokat ad. A Mistral ingyenes csomagját használja a saját szabad kulcsoddal (a regisztráció telefonos ellenőrzést igényel); a memória ezen a számítógépen marad.\n\nA Mistral körülbelül másodpercenként egy üzenetet enged, és van havi keret.\n\nMistral vagy Helyi esetén a Convai felhőhangját helyi hang váltja. A beszédfelismerés ezen a számítógépen történik, így a hangkulcs működik.",
    ["Who writes your companions’ replies. A change waits until no conversation is running; choose Apply.\n\nConvai needs no setup and gives better replies. Mistral uses its free plan with your own free key (signing up needs phone verification); memory stays on this computer.\n\nMistral allows about one message a second and a monthly allowance.\n\nWith Mistral or Local, Convai’s cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with them, so type your messages."] = "Ki írja a társaid válaszait. A változtatás addig vár, amíg nem fut beszélgetés; válaszd az Alkalmaz lehetőséget.\n\nA Convai nem igényel beállítást, és jobb válaszokat ad. A Mistral ingyenes csomagját használja a saját szabad kulcsoddal (a regisztráció telefonos ellenőrzést igényel); a memória ezen a számítógépen marad.\n\nA Mistral körülbelül másodpercenként egy üzenetet enged, és van havi keret.\n\nMistral vagy Helyi esetén a Convai felhőhangját helyi hang váltja. A hangkulcshoz szükséges beszédfelismerés még nem érhető el velük, ezért írd be az üzeneteidet.",
    ["Your changes work with Mistral and Local. They do not apply to Convai."] = "A módosításaid Mistral és Local mellett működnek. Convai esetén nem érvényesek.",
}
